<template>
<section class="order-desk page-stack">
  <header><p class="eyebrow">我的书院</p><h2>我的订单</h2></header>
  <nav class="types" aria-label="订单类型"><button v-for="(label,k) in types" :key="k" :aria-pressed="type===k" @click="filter(k,'ALL')">{{label}}</button></nav>
  <nav class="stages" aria-label="订单状态"><button v-for="(label,k) in stages" :key="k" :aria-pressed="stage===k" @click="filter(type,k)">{{label}} <small v-if="data">{{data.counts[k]}}</small></button></nav>
  <p v-if="error" role="alert">{{error}} <el-button @click="load">重试</el-button></p><p v-else-if="!data" role="status">正在加载订单…</p><p v-else-if="!data.items.length" class="empty">这里还没有{{type==='ALL'?'':types[type]}}记录</p>
  <article v-for="r in data?.items" :key="r.kind+':'+r.id" class="order-row"><div class="line"><small>{{kindName(r)}} · {{roleLabels[r.role]}}</small><span>{{label(r)}}</span></div><h3>{{r.title}}</h3><div class="line"><small>{{date(r.createdAt)}}<template v-if="r.interested"> · {{r.interested}} 人{{r.kind==='TASK'?'报名':'想要'}}</template></small><b v-if="r.amount!==null"><small v-if="goodsDestination(r) && r.status==='COMPLETED'">成交价 </small>¥{{r.amount}}</b></div><router-link v-if="goodsDestination(r)" class="link" :to="goodsDestination(r)">查看商品</router-link><button class="link" @click="openRow(r)">查看记录 →</button></article>
  <el-pagination v-if="data && data.total>20" layout="prev, pager, next" :page-size="20" :total="data.total" :current-page="page+1" @current-change="(n:number)=>{page=n-1;load()}" />
  <el-dialog :model-value="!!current" title="订单详情" width="min(480px,92vw)" @close="dismiss"><template v-if="current"><small>{{kindName(current)}} · {{roleLabels[current.role]}} · {{label(current)}}</small><h3>{{current.title}}</h3><p>{{date(current.createdAt)}}<span v-if="current.amount!==null"> · {{goodsDestination(current) && current.status==='COMPLETED'?'成交价 ':''}}¥{{current.amount}}</span></p>
  <template v-if="booking"><p>{{booking.shopName}} · 预约 {{date(booking.appointmentTime)}}</p><p v-if="booking.note">{{booking.note}}</p><p v-if="booking.cancelReason">原因：{{booking.cancelReason}}</p><p v-if="booking.contactSnapshot && current.role==='CUSTOMER'">店主联系方式：{{booking.contactSnapshot}}</p><el-button v-for="a in actions(current.role,current.status)" :key="a.key" :disabled="busy" @click="act(a.key,a.label)">{{a.label}}</el-button></template>
  <p v-if="current.kind==='TASK'&&current.role==='APPLICANT'">{{current.status==='REJECTED'?'这次未被选中。':'报名结果以这条记录为准。'}}</p>
  <el-button v-if="jump" text type="primary" @click="router.push(jump)">{{current.kind==='TASK'?'进入履约台':goodsDestination(current)?'查看商品':'查看'+kindName(current)}} →</el-button>
  <el-button v-if="current.kind==='PROJECT'" text @click="router.push('/project-ads/manage')">管理宣传</el-button>
  <div class="feedback"><el-button v-if="current.canReview" :disabled="busy" @click="selectMode('review')">写评价</el-button><span v-if="current.reviewed">已评价</span><el-button v-if="current.canComplain" text :disabled="busy" @click="selectMode('complaint')">投诉此单</el-button><span v-if="current.complained">已投诉</span></div>
  <form v-if="mode" @submit.prevent="send"><label v-if="mode==='review'">评分 <el-rate v-model="stars" /></label><el-input v-else v-model="reason" maxlength="120" placeholder="投诉原因"/><el-input v-model="message" type="textarea" :rows="3" maxlength="1000" :placeholder="mode==='review'?'说说这次体验（选填）':'补充说明（选填）'"/><el-button native-type="submit" type="primary" :loading="busy" :disabled="mode==='review'?!stars:!reason.trim()">提交{{mode==='review'?'评价':'投诉'}}</el-button></form></template></el-dialog>
</section></template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {formatStatus} from '@/utils/display'
import {types,stages,roleLabels,actions,typeParam,stageParam,goodsDestination,listOrders,loadRow,bookingDetail,bookingAction,submitRating,submitComplaint,type DeskRow,type DeskPage,type Type,type Stage} from '@/api/orderDesk'
const auth=useAuthStore(),route=useRoute(),router=useRouter();const type=computed(()=>typeParam(route.query.type)),stage=computed(()=>stageParam(route.query.stage));const page=ref(0),data=ref<DeskPage|null>(null),error=ref(''),current=ref<DeskRow|null>(null),booking=ref<Awaited<ReturnType<typeof bookingDetail>>|null>(null),busy=ref(false),mode=ref(''),stars=ref(0),reason=ref(''),message=ref('');let seq=0,detailSeq=0
const date=(s:string)=>s?.slice(0,16).replace('T',' ');const kindName=(r:DeskRow)=>r.kind.startsWith('GOODS')?'二手':types[r.kind as Type]||'记录';const label=(r:DeskRow)=>r.role==='APPLICANT'&&['PENDING','APPLIED'].includes(r.status)?'已报名':r.kind==='GOODS_INTENT'&&r.status==='OPEN'?'已联系':r.kind==='GOODS_LISTING'&&r.status==='PUBLISHED'?'在售':formatStatus(r.status)
const jump=computed(()=>{const r=current.value;if(!r)return '';if(r.kind==='TASK')return r.role==='APPLICANT'?'':`/tasks/${r.objectId}/workspace`;if(r.kind==='PROJECT')return `/project-ads/${r.objectId}`;if(goodsDestination(r))return goodsDestination(r);return booking.value?`/shops/${booking.value.shopId}`:''})
function filter(t:Type,s:Stage){void router.replace({query:{type:t,stage:s}})}
function selectMode(next:string){mode.value=next;message.value='';reason.value='';stars.value=0}
function dismiss(){detailSeq++;current.value=null;booking.value=null;mode.value='';reason.value='';message.value='';stars.value=0;busy.value=false}
async function load(){const id=++seq;data.value=null;error.value='';if(!auth.currentUser)return;try{const result=await listOrders(type.value,stage.value,page.value);if(id===seq)data.value=result}catch(e){if(id===seq)error.value=e instanceof Error?e.message:'订单加载失败'}}
async function openRow(r:DeskRow){dismiss();const v=detailSeq;try{const [row,b]=await Promise.all([loadRow(r),r.kind==='BOOKING'?bookingDetail(r.id):null]);if(v===detailSeq){current.value=row;booking.value=b}}catch(e){if(v===detailSeq)ElMessage.error(e instanceof Error?e.message:'无法查看记录')}}
async function act(key:string,title:string){const r=current.value,v=detailSeq;if(!r||busy.value)return;busy.value=true;try{let why:string|undefined;if(['reject','cancel'].includes(key)){why=(await ElMessageBox.prompt('原因',title,{inputPattern:/\S/,inputErrorMessage:'请填写原因'})).value}else await ElMessageBox.confirm('确认更新这笔预约？',title);if(v!==detailSeq)return;await bookingAction(r.id,key,why);if(v===detailSeq){dismiss();await load()}}catch(e){if(e instanceof Error&&v===detailSeq)ElMessage.error(e.message)}finally{if(v===detailSeq)busy.value=false}}
async function send(){const r=current.value,v=detailSeq;if(!r||busy.value)return;busy.value=true;try{if(mode.value==='review')await submitRating(r,stars.value,message.value);else await submitComplaint(r,reason.value,message.value);if(v===detailSeq){ElMessage.success('已提交');dismiss();await load()}}catch(e){if(v===detailSeq)ElMessage.error(e instanceof Error?e.message:'提交失败')}finally{if(v===detailSeq)busy.value=false}}
watch([type,stage,()=>auth.token,()=>auth.currentUser?.id],()=>{page.value=0;dismiss();void load()},{immediate:true,flush:'sync'});onBeforeUnmount(()=>{seq++;dismiss()})
</script>
<style scoped>.order-desk{max-width:880px}.order-desk h2,.order-desk h3{margin:.35rem 0}.types,.stages,.feedback{display:flex;flex-wrap:wrap;gap:.55rem}.types button,.stages button,.link{background:none;border:0;cursor:pointer;color:inherit;padding:.45rem .7rem}.types button[aria-pressed=true]{border-bottom:2px solid var(--accent-primary);font-weight:700}.stages button[aria-pressed=true]{background:var(--bg-surface-warm);border-radius:6px}.order-row{border-bottom:1px solid var(--border-strong);padding:.75rem 0;overflow-wrap:anywhere}.line{display:flex;justify-content:space-between;align-items:baseline;gap:1rem}.order-row small,.empty{color:var(--text-secondary)}.link{color:var(--accent-primary);padding-left:0}.feedback{margin:1rem 0}form{display:grid;gap:.75rem}</style>
